import{It as e,bt as t,nt as n,yt as r}from"./chunks/framework.D2FS3J_H.js";var i=JSON.parse(`{"title":"Hybrid Editor","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/editor.md","filePath":"docs/editor.md"}`),a={name:`docs/editor.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hybrid-editor" tabindex="-1">Hybrid Editor <a class="header-anchor" href="#hybrid-editor" aria-label="Permalink to “Hybrid Editor”">​</a></h1><p>The editor shows a diagram twice: as text on the left, and as a picture on the right. Both are views of the same document, and both can be edited. The picture is not generated <em>from</em> the text once and then detached - every graphical edit is turned back into a text edit, so the text always is the diagram.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The embedded editors in this documentation are the same editor, only smaller. Everything described here can be tried out directly on the diagram type pages.</p></div><h2 id="the-workspace" tabindex="-1">The workspace <a class="header-anchor" href="#the-workspace" aria-label="Permalink to “The workspace”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What it is</th></tr></thead><tbody><tr><td>Left pane</td><td>The <a href="#textual-editor">textual editor</a>, based on Monaco (the editor of VS Code)</td></tr><tr><td>Right pane</td><td>The <a href="#graphical-editor">graphical editor</a>, including the toolbox</td></tr><tr><td>Divider</td><td>Drag it to give one side more room</td></tr><tr><td>Navigation bar</td><td>Diagram selection, share link, save, download and settings</td></tr></tbody></table><p>The panes are side by side, and switch to stacked on narrow, tall screens such as a phone in portrait mode.</p><h2 id="textual-editor" tabindex="-1">Textual editor <a class="header-anchor" href="#textual-editor" aria-label="Permalink to “Textual editor”">​</a></h2><p>The textual editor is a full language client - the language server which powers it also renders the diagram, so both views always agree on what the document means.</p><ul><li><strong>Syntax highlighting</strong></li><li><strong>Auto-completion</strong>, including documentation for functions, parameters and style attributes. Completion is offered where a value is expected, so it knows about the elements and the styles of the diagram type you are using.</li><li><strong>Error highlighting</strong> for lexer, parser, interpreter and layout errors, as squiggles in the text and, where possible, at the position which caused them.</li><li><strong>Auto-formatting</strong> of the whole document (<code>Shift</code> + <code>Alt</code> + <code>F</code>), which also normalizes indentation of nested blocks.</li><li><strong>Reveal</strong>: double-clicking an element in the diagram selects the expression which created it.</li></ul><p>Because the document is an ordinary text document, everything you expect from a code editor works: multiple cursors, find and replace, and an undo stack which also contains all graphical edits.</p><h2 id="graphical-editor" tabindex="-1">Graphical editor <a class="header-anchor" href="#graphical-editor" aria-label="Permalink to “Graphical editor”">​</a></h2><h3 id="navigating-the-canvas" tabindex="-1">Navigating the canvas <a class="header-anchor" href="#navigating-the-canvas" aria-label="Permalink to “Navigating the canvas”">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Zoom</td><td>Mouse wheel or trackpad pinch</td></tr><tr><td>Pan</td><td>Drag the empty canvas, hold <code>Space</code> and drag, or drag with middle mouse</td></tr><tr><td>Pan (hand tool)</td><td>Select the hand tool in the toolbox, then drag anywhere</td></tr><tr><td>Fit diagram</td><td><code>Ctrl</code> + <code>Shift</code> + <code>F</code></td></tr><tr><td>Center diagram</td><td><code>Ctrl</code> + <code>Shift</code> + <code>C</code></td></tr></tbody></table><h3 id="selecting" tabindex="-1">Selecting <a class="header-anchor" href="#selecting" aria-label="Permalink to “Selecting”">​</a></h3><p>Click an element to select it, <code>Ctrl</code> + click to add or remove an element from the selection. The box select tool selects everything inside a dragged rectangle; holding <code>Shift</code> while starting the box keeps the current selection.</p><h3 id="moving-resizing-and-rotating" tabindex="-1">Moving, resizing and rotating <a class="header-anchor" href="#moving-resizing-and-rotating" aria-label="Permalink to “Moving, resizing and rotating”">​</a></h3><p>Selected elements can be dragged. What can be moved, and how far, follows from the source: an element positioned with <code>apos</code> moves freely, an element positioned with <code>rpos</code> moves relative to its target, and an element whose position is computed cannot be dragged at all.</p><p>Resizing works by dragging the border or a corner of a selected element, rotating by dragging the rotate handle shown next to it. Both write plain numbers into the <code>layout</code> block of the element.</p><h3 id="snapping" tabindex="-1">Snapping <a class="header-anchor" href="#snapping" aria-label="Permalink to “Snapping”">​</a></h3><p>While dragging, the editor snaps to the grid, to other elements and to gaps between elements, and shows snap lines for what it snapped to. Hold <code>Alt</code> while dragging to invert this: with snapping enabled it drags freely, with snapping disabled it snaps. Grid and snapping can be turned off entirely in the <a href="#settings">settings</a>.</p><p>How precise the resulting numbers are is a setting as well - by default, positions and sizes are rounded to whole pixels, so the source stays readable.</p><h3 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to “Connections”">​</a></h3><ul><li><strong>Creating</strong>: select the connect tool, pick the connection operator to use, then drag from the source element to the target element.</li><li><strong>Shaping</strong>: drag the connection to move it, drag its points to reroute it. The points of an axis-aligned connection only move along their axis.</li><li><strong>Splitting</strong>: <code>Shift</code> + click on a selected connection inserts a new point at that position, splitting the segment into two.</li><li><strong>Line points</strong>: points which sit on an element outline or on another connection are dragged along that line; hold <code>Shift</code> to keep the distance to the line fixed and only change the position on it.</li><li><strong>Labels</strong>: labels of a connection are dragged like any other element, which changes their relative position and distance.</li></ul><h3 id="toolbox" tabindex="-1">Toolbox <a class="header-anchor" href="#toolbox" aria-label="Permalink to “Toolbox”">​</a></h3><p>The toolbox sits in the corner of the graphical editor and is opened and closed with the pencil button.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td>Hand</td><td>Dragging pans the canvas instead of moving elements</td></tr><tr><td>Default</td><td>Select, move, resize and rotate</td></tr><tr><td>Add element</td><td>Shows the elements which can be added, click or drag one onto the canvas to add it</td></tr><tr><td>Connect</td><td>Shows the connection operators of the diagram type, drag from source to target to connect</td></tr><tr><td>Box select</td><td>Drag a rectangle to select everything inside it</td></tr></tbody></table><p>Clicking the active add-element or connect tool again locks it, so it stays active after use and you can add several elements in a row - a small lock is shown on the tool.</p><p>The element list is grouped and searchable, and each entry shows a preview of what will be added. The preview is not a picture drawn for the toolbox: it is the actual diagram, rendered by the language server as if the edit had already been applied.</p><p>If exactly one element is selected, the toolbox offers what can be added <em>to that element</em> - a port on a component, a member on a class - instead of what can be added to the diagram.</p><h3 id="reaching-the-source" tabindex="-1">Reaching the source <a class="header-anchor" href="#reaching-the-source" aria-label="Permalink to “Reaching the source”">​</a></h3><p>Double-click an element, or <code>Alt</code> + click it, to select the expression which created it in the text editor. This is the fastest way from <em>this box here</em> to the place in the source which is responsible for it.</p><h2 id="undo-and-redo" tabindex="-1">Undo and redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to “Undo and redo”">​</a></h2><p><code>Ctrl</code> + <code>Z</code> and <code>Ctrl</code> + <code>Y</code> (or <code>Ctrl</code> + <code>Shift</code> + <code>Z</code>) work in both panes and share one history, because a graphical edit is a text edit. A drag is a single undo step, no matter how many intermediate positions were rendered while dragging.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h2><p>The settings are opened with the gear button in the navigation bar.</p><h3 id="graphical-editor-1" tabindex="-1">Graphical editor <a class="header-anchor" href="#graphical-editor-1" aria-label="Permalink to “Graphical editor”">​</a></h3><p>The precision settings define how the numbers written by graphical edits are rounded.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td>Absolute/relative point translation precision</td><td><code>1</code></td><td>Rounding of <code>x</code>/<code>y</code> when moving points and elements</td></tr><tr><td>Resize precision</td><td><code>1</code></td><td>Rounding of <code>width</code>/<code>height</code> when resizing</td></tr><tr><td>Line point pos precision</td><td><code>0.001</code></td><td>Rounding of the relative position of a line point</td></tr><tr><td>Line point distance precision</td><td><code>0.1</code></td><td>Rounding of the distance of a line point to its line</td></tr><tr><td>Axis aligned pos precision</td><td><code>0.001</code></td><td>Rounding of the relative position of an axis-aligned segment</td></tr><tr><td>Rotation precision</td><td><code>1</code></td><td>Rounding of the rotation angle in degrees</td></tr><tr><td>Grid</td><td>on</td><td>Show the grid and snap to it</td></tr><tr><td>Snap to elements/points</td><td>on</td><td>Snap to other elements, points and gaps</td></tr></tbody></table><h3 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to “Theme”">​</a></h3><p>The primary color (strokes and text) and the background color can be set separately for light and dark mode. They are also available in diagrams as the <code>primary</code> and <code>background</code><a href="./diagram.html#style-variables">style variables</a>, so a diagram which uses them renders correctly in both modes. The light/dark toggle of the page switches the diagram along with the documentation.</p><h3 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to “Diagram”">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td>Font subsetting</td><td>on</td><td>Embed only the glyphs actually used, which makes exported files much smaller</td></tr><tr><td>External fonts</td><td>off</td><td>Allow loading fonts from external URLs, needed for diagrams which use a font from e.g. Google Fonts</td></tr></tbody></table><h2 id="diagrams-and-files" tabindex="-1">Diagrams and files <a class="header-anchor" href="#diagrams-and-files" aria-label="Permalink to “Diagrams and files”">​</a></h2><p>The editor is a progressive web app: it runs completely in the browser, works offline once it has been loaded, and can be installed like a native application. No diagram is ever sent to a server.</p><ul><li><strong>Storage</strong>: diagrams are stored in the browser and are listed in the diagram selection in the navigation bar, where they can be created, opened and deleted. The most recently edited diagram is opened on start.</li><li><strong>Files</strong>: a <code>.hyl</code> file can be opened from disk, and - in browsers which support it - saved back to the same file with <code>Ctrl</code> + <code>S</code>. If the browser does not support writing files, <code>Ctrl</code> + <code>S</code> downloads the source instead. When installed as an app, HyLiMo can be registered as the handler for <code>.hyl</code> files.</li><li><strong>Sharing</strong>: the link button copies a URL which contains the compressed source of the diagram, so it can be shared without any server storing it.</li><li><strong>Export</strong>: the download menu offers SVG, SVG with text converted to paths (for consumers which ignore embedded fonts, such as PowerPoint), PDF, and the source file itself.</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to “Keyboard shortcuts”">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> + <code>S</code></td><td>Save the diagram, or download the source</td></tr><tr><td><code>Ctrl</code> + <code>Shift</code> + <code>E</code></td><td>Download the diagram as SVG</td></tr><tr><td><code>Ctrl</code> + <code>Z</code> / <code>Ctrl</code> + <code>Y</code></td><td>Undo / redo, in both panes</td></tr><tr><td><code>Ctrl</code> + <code>Shift</code> + <code>F</code></td><td>Fit the diagram to the screen</td></tr><tr><td><code>Ctrl</code> + <code>Shift</code> + <code>C</code></td><td>Center the diagram</td></tr><tr><td><code>Shift</code> + <code>Alt</code> + <code>F</code></td><td>Format the document</td></tr><tr><td><code>Ctrl</code> + <code>Space</code></td><td>Trigger auto-completion</td></tr><tr><td><code>Space</code> + drag, or middle mouse drag</td><td>Pan the canvas</td></tr><tr><td><code>Ctrl</code> + click</td><td>Add/remove an element from the selection</td></tr><tr><td>Double click, or <code>Alt</code> + click</td><td>Reveal the element in the text editor</td></tr><tr><td><code>Alt</code> + drag</td><td>Invert snapping while dragging</td></tr><tr><td><code>Shift</code> + click on a selected connection</td><td>Split the connection segment</td></tr><tr><td><code>Shift</code> + drag a line point</td><td>Keep the distance to the line, change only position</td></tr></tbody></table><p>On macOS, use <code>Cmd</code> instead of <code>Ctrl</code>.</p>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};